87	int network_wait_connected(uint32_t timeout_ms)
88	{
89	    if (timeout_ms == 0) {
90	        return network_is_connected() ? OK : ERROR;
91	    }
92	
93	    struct timespec deadline;
94	    clock_gettime(CLOCK_REALTIME, &deadline);
95	    deadline.tv_sec += (time_t)(timeout_ms / 1000);
96	    deadline.tv_nsec += (long)((timeout_ms % 1000) * 1000000L);
97	    if (deadline.tv_nsec >= 1000000000L) {
98	        deadline.tv_sec++;
99	        deadline.tv_nsec -= 1000000000L;
100	    }
101	
102	    while (1) {
103	        if (network_is_connected()) {
104	            syslog(LOG_INFO, "[%s] Network connected: %s\n", TAG, s_ip_str);
105	            return OK;
106	        }
107	
108	        struct timespec now;
109	        clock_gettime(CLOCK_REALTIME, &now);
110	        if (now.tv_sec > deadline.tv_sec || (now.tv_sec == deadline.tv_sec && now.tv_nsec >= deadline.tv_nsec)) {
111	            syslog(LOG_WARNING, "[%s] Timed out waiting for network\n", TAG);
112	            return ERROR;
113	        }
114	
115	        usleep(500000); /* poll every 500 ms */
116	    }
117	}
