916	    const char* ssid, const char* pass, bool persist)
917	{
918	    if (!ssid || ssid[0] == '\0') {
919	        syslog(LOG_ERR, "[%s] wifi_connect: SSID required\n", TAG);
920	        return ERROR;
921	    }
922	
923	    const char* dev = (iface && iface[0]) ? iface : "wlan0";
924	
925	    syslog(LOG_INFO, "[%s] Connecting WiFi on %s\n", TAG, dev);
926	
927	    if (netlib_ifup(dev) < 0) {
928	        syslog(LOG_ERR, "[%s] ifup %s failed: %d\n", TAG, dev, errno);
929	        return ERROR;
930	    }
931	
932	    usleep(500000); /* wait for driver ready */
933	
934	    if (network_wifi_configure_wapi(dev, ssid, pass) < 0) {
935	        syslog(LOG_ERR,
936	            "[%s] WiFi association timed out; check the password and "
937	            "use a 2.4 GHz WPA2 hotspot\n",
938	            TAG);
939	        return ERROR;
940	    }
941	
942	    if (network_wifi_wait_associated(dev) < 0) {
943	        return ERROR;
944	    }
945	
946	    /* The station link event can precede readiness for DHCP traffic.
947	     * Allow the link to settle, then retry renew without reconnecting or
948	     * reapplying credentials.
949	     */
950	
951	    usleep(WIFI_DHCP_DELAY_US);
952	    for (int retry = 0; retry < WIFI_DHCP_RETRIES; retry++) {
953	        int dhcp_ret = netlib_obtain_ipv4addr(dev);
954	        if (dhcp_ret == OK) {
955	            break;
956	        }
957	
958	        syslog(LOG_ERR,
959	            "[%s] DHCP attempt %d/%d failed: ret=%d errno=%d\n",
960	            TAG, retry + 1, WIFI_DHCP_RETRIES, dhcp_ret, errno);
961	        if (retry + 1 == WIFI_DHCP_RETRIES) {
962	            syslog(LOG_ERR, "[%s] DHCP failed after %d attempts\n",
963	                TAG, WIFI_DHCP_RETRIES);
964	            return ERROR;
965	        }
966	
967	        usleep(WIFI_DHCP_DELAY_US);
968	    }
969	
970	    if (network_wait_connected(15000) < 0) {
971	        syslog(LOG_WARNING, "[%s] No IP after DHCP\n", TAG);
972	        return ERROR;
973	    }
974	
975	    /* Save only credentials that completed association and DHCP.  Always
