    }

    agent_config_get(AGENT_CFG_KEY_WIFI_PASS, pass, sizeof(pass));
    pthread_mutex_lock(&s_wifi_lock);
    ret = network_wifi_connect_internal(NULL, ssid, pass, false);
    pthread_mutex_unlock(&s_wifi_lock);
    return ret;
}

