108	static int save_json(cJSON *root)
109	{
110	    const char *temporary = AGENT_CONFIG_FILE ".tmp";
111	    size_t length;
112	    size_t padded_length;
113	    size_t offset;
114	    int saved_errno;
115	    int fd = -1;
116	
117	    /* Serialize directly into internal DRAM.  Heap-backed cJSON output can
118	     * reside in SPIRAM, which is not a safe SD/MMC DMA source on this board. */
119	    if (!cJSON_PrintPreallocated(root, s_json_buffer,
120	            sizeof(s_json_buffer), false)) {
121	        errno = ENOSPC;
122	        return ERROR;
123	    }
124	
125	    length = strlen(s_json_buffer);
126	    padded_length = (length + CONFIG_STORE_BLOCK_SIZE - 1) &
127	        ~(CONFIG_STORE_BLOCK_SIZE - 1);
128	    if (length < 2 || padded_length >= sizeof(s_json_buffer) ||
129	        s_json_buffer[0] != '{' || s_json_buffer[length - 1] != '}') {
130	        errno = ENOSPC;
131	        return ERROR;
132	    }
133	
134	    /* Keep every SD transfer sector-sized and aligned.  JSON permits trailing
135	     * whitespace, so padding with spaces avoids a short final DMA transfer. */
136	    memset(s_json_buffer + length, ' ', padded_length - length);
137	
138	    fd = open(temporary, O_WRONLY | O_CREAT | O_TRUNC, 0600);
139	    if (fd < 0)
140	        return ERROR;
141	
142	    for (offset = 0; offset < padded_length;
143	         offset += CONFIG_STORE_BLOCK_SIZE) {
144	        ssize_t written;
145	        do {
146	            written = write(fd, s_json_buffer + offset,
147	                            CONFIG_STORE_BLOCK_SIZE);
148	        } while (written < 0 && errno == EINTR);
149	
150	        if (written != CONFIG_STORE_BLOCK_SIZE) {
151	            if (written >= 0)
152	                errno = EIO;
153	            goto fail_fd;
154	        }
155	    }
156	
157	    if (fsync(fd) < 0)
158	        goto fail_fd;
159	
160	    if (close(fd) < 0) {
161	        saved_errno = errno;
162	        fd = -1;
163	        unlink(temporary);
164	        errno = saved_errno;
165	        return ERROR;
166	    }
167	    fd = -1;
168	
169	    /* Verify all sectors before publishing the temporary file. */
170	    fd = open(temporary, O_RDONLY);
171	    if (fd < 0)
172	        goto fail_unlink;
173	
174	    for (offset = 0; offset < padded_length;
175	         offset += CONFIG_STORE_BLOCK_SIZE) {
176	        ssize_t count;
177	        do {
178	            count = read(fd, s_io_staging, CONFIG_STORE_BLOCK_SIZE);
179	        } while (count < 0 && errno == EINTR);
180	
181	        if (count != CONFIG_STORE_BLOCK_SIZE ||
182	            memcmp(s_io_staging, s_json_buffer + offset,
183	                   CONFIG_STORE_BLOCK_SIZE) != 0) {
184	            errno = EIO;
185	            syslog(LOG_ERR, "[%s] SD config verification failed\n", TAG);
186	            goto fail_fd;
187	        }
188	    }
189	
190	    if (close(fd) < 0) {
191	        saved_errno = errno;
192	        fd = -1;
193	        unlink(temporary);
194	        errno = saved_errno;
195	        return ERROR;
196	    }
197	    fd = -1;
198	
199	    if (rename(temporary, AGENT_CONFIG_FILE) < 0)
200	        goto fail_unlink;
201	
202	    return OK;
203	
204	fail_fd:
205	    saved_errno = errno;
206	    if (fd >= 0)
207	        close(fd);
208	    unlink(temporary);
209	    errno = saved_errno;
210	    return ERROR;
211	
212	fail_unlink:
213	    saved_errno = errno;
214	    unlink(temporary);
215	    errno = saved_errno;
