    {
      memset(wifi_cfg.sta.ssid, 0x0, SSID_MAX_LEN);
      memcpy(wifi_cfg.sta.ssid, pdata, len);
      wifi_cfg.sta.channel = 0; /* Scan all channels; phone hotspots may move. */
