private void setBleStatus(String message) {
    bleStatusView.setText(getString(R.string.ble_status_format, message));
}

private void provisionBoard() {
    if (requestBlePermission()) {
        return;
    }
    VlogService.StatusSnapshot current = VlogService.getStatusSnapshot();
    if (!VlogService.STATE_RUNNING.equals(current.state)
            && !VlogService.STATE_GENERATING.equals(current.state)) {
        Toast.makeText(this, "请先启动手机后端服务", Toast.LENGTH_LONG).show();
        return;
    }
    try {
        String ssid = hotspotSsidInput.getText().toString();
        String password = hotspotPasswordInput.getText().toString();
        config.setHotspotCredentials(ssid, password);
        String endpoint = AppNetwork.getEndpoint(this, config);
        URI uri = URI.create(endpoint);
        if (!"http".equalsIgnoreCase(uri.getScheme()) || uri.getHost() == null
                || uri.getPort() != 8080) {
