      case WPA_VER_NONE:
        auth_wpa = IW_AUTH_WPA_VERSION_DISABLED;
        break;

      case WPA_VER_1:
        auth_wpa = IW_AUTH_WPA_VERSION_WPA;
        break;

      case WPA_VER_2:
        auth_wpa = IW_AUTH_WPA_VERSION_WPA2;
        break;

      case WPA_VER_3:
        auth_wpa = IW_AUTH_WPA_VERSION_WPA3;
        break;

      default:
        return -EINVAL;
