static int network_wifi_connect_internal(const char* iface,
    const char* ssid, const char* pass, bool persist)
{
    if (!ssid || ssid[0] == '\0') {
        syslog(LOG_ERR, "[%s] wifi_connect: SSID required\n", TAG);
        return ERROR;
    }

    const char* dev = (iface && iface[0]) ? iface : "wlan0";

    syslog(LOG_INFO, "[%s] Connecting WiFi on %s\n", TAG, dev);

    if (netlib_ifup(dev) < 0) {
        syslog(LOG_ERR, "[%s] ifup %s failed: %d\n", TAG, dev, errno);
        return ERROR;
    }

    usleep(500000); /* wait for driver ready */

    if (network_wifi_configure_wapi(dev, ssid, pass) < 0) {
        syslog(LOG_ERR,
            "[%s] WiFi association timed out; check the password and "
            "use a 2.4 GHz WPA2 hotspot\n",
            TAG);
        return ERROR;
    }

    if (network_wifi_wait_associated(dev) < 0) {
        return ERROR;
    }

    /* The station link event can precede readiness for DHCP traffic.
     * Allow the link to settle, then retry renew without reconnecting or
     * reapplying credentials.
     */

    usleep(WIFI_DHCP_DELAY_US);
    for (int retry = 0; retry < WIFI_DHCP_RETRIES; retry++) {
        int dhcp_ret = netlib_obtain_ipv4addr(dev);
        if (dhcp_ret == OK) {
            break;
        }

        syslog(LOG_ERR,
            "[%s] DHCP attempt %d/%d failed: ret=%d errno=%d\n",
            TAG, retry + 1, WIFI_DHCP_RETRIES, dhcp_ret, errno);

