{
  struct aivlog_cloud_manifest_s manifest;
  char root[AIVLOG_CLOUD_PATH_SIZE];
  FAR struct dirent *entry;
  FAR DIR *directory;
  uint32_t session_id;
  unsigned int sessions = 0;
