name: cla-check

on:
  pull_request_target:
    types: [opened, reopened, synchronize]
  issue_comment:
    types: [created]
  workflow_call:

permissions:
  contents: read
  pull-requests: write
  statuses: write
  checks: write

# One group per pull request. github.event.pull_request is absent on
# issue_comment events, so without github.event.issue.number the fallback would
# be github.ref -- identical for every /check-cla in a repository, making
# concurrent re-checks on different PRs cancel each other and leave all but one
# without a cla/signature status.
concurrency:
  group: cla-check-${{ github.event.pull_request.number || github.event.issue.number || github.ref }}
  cancel-in-progress: true

jobs:
  cla-check:
    if: github.event_name == 'pull_request_target' || github.event_name == 'pull_request' || github.event_name == 'workflow_call' || (github.event.issue.pull_request && contains(github.event.comment.body, '/check-cla'))
    runs-on: ubuntu-latest
    steps:
      - name: Get PR Info
        id: pr-info
        uses: actions/github-script@v7
        with:
          script: |
            let pr;
            let triggerType = 'pr'; // 'pr' or 'comment'

