          echo "unsigned=$UNSIGNED_EMAILS" >> $GITHUB_OUTPUT
          echo "error=" >> $GITHUB_OUTPUT

          if [ "$ALL_SIGNED" = true ]; then
            echo "signed=true" >> $GITHUB_OUTPUT
